<?php
require "config.php";require "funciones_correo.php";
$id=(int)($_GET['id']??$_POST['id']??0);$s=$conexion->prepare("SELECT * FROM certificados WHERE id=? LIMIT 1");$s->bind_param('i',$id);$s->execute();$r=$s->get_result();if(!$r||!$r->num_rows)die('Participante no encontrado.');$c=$r->fetch_assoc();$msg='';$ok=false;
if($_SERVER['REQUEST_METHOD']==='POST'){$ruta=__DIR__.'/certificados/'.basename($c['archivo']??'');[$ok,$msg]=enviarCertificado($c,$ruta);if($ok){$u=$conexion->prepare("UPDATE certificados SET fecha_envio=NOW(),estado_correo='ENVIADO' WHERE id=?");$u->bind_param('i',$id);$u->execute();}}
$generado=!empty($c['archivo'])&&is_file(__DIR__.'/certificados/'.$c['archivo']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enviar certificado</title><style>body{font-family:Arial;background:#eee;padding:30px}.box{max-width:650px;margin:auto;background:#fff;padding:30px;border-radius:12px}a,button{display:inline-block;padding:12px 16px;background:#9b741c;color:#fff;border:0;border-radius:6px;text-decoration:none;cursor:pointer}.msg{padding:12px;background:<?=$ok?'#d9f2df':'#fff0c2'?>}</style></head><body><div class="box"><a href="listado.php">← Volver al listado</a><h2>Enviar certificado por correo</h2><p><b>Participante:</b> <?=htmlspecialchars($c['nombre'].' '.$c['apellido'])?></p><p><b>Correo:</b> <?=htmlspecialchars($c['correo']??'No registrado')?></p><p><b>Certificado:</b> <?=$generado?'Generado':'Pendiente de generar'?></p><?php if($msg):?><p class="msg"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if(!$generado):?><p>Primero debe generar el certificado.</p><a href="generar.php?id=<?=$id?>">GENERAR CERTIFICADO</a><?php elseif(empty($c['correo'])||!filter_var($c['correo'],FILTER_VALIDATE_EMAIL)):?><p>Registre un correo válido en la base de datos o vuelva a importar la fila con correo.</p><?php else:?><form method="post"><input type="hidden" name="id" value="<?=$id?>"><button>ENVIAR CERTIFICADO</button></form><?php endif;?></div></body></html>